# Writes the Jarvis Android project into ./android-app (run by GitHub Actions).
import base64, os
FILES = {
"build.gradle": "cGx1Z2lucyB7CiAgICBpZCAnY29tLmFuZHJvaWQuYXBwbGljYXRpb24nIHZlcnNpb24gJzguNS4yJyBhcHBseSBmYWxzZQp9Cg==",
"gradle.properties": "b3JnLmdyYWRsZS5qdm1hcmdzPS1YbXgyMDQ4bSAtRGZpbGUuZW5jb2Rpbmc9VVRGLTgKYW5kcm9pZC5ub25UcmFuc2l0aXZlUkNsYXNzPXRydWUK",
"settings.gradle": "",
"app/build.gradle": "",
"app/src/main/AndroidManifest.xml": "",
"app/src/main/java/com/jarvis/assistant/MainActivity.java": "",
"app/src/main/java/com/jarvis/assistant/Actions.java": "",
"app/src/main/java/com/jarvis/assistant/Brain.java": "",
"app/src/main/java/com/jarvis/assistant/ReactorView.java": "",
"app/src/main/java/com/jarvis/assistant/JarvisService.java": "",
"app/src/main/res/mipmap-xxhdpi/ic_launcher.png": ""
}
for rel, b64 in FILES.items():
    path = os.path.join("android-app", rel)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "wb") as fh:
        fh.write(base64.b64decode(b64))
print("wrote", len(FILES), "files")
